            "ip addr show eth0",
            "ip route",
            "cat /etc/network/interfaces",
        ]
        for cmd in cmds:
            try:
                out = conn.send_command(cmd, read_timeout=10)
                results[cmd] = out
            except Exception as e:
                results[cmd] = f"ERROR: {e}"
        conn.disconnect()
    except Exception as e:
        results["CONNECTION_ERROR"] = str(e)
    return name, results


def main():
