        for name, params in MIKROTIK_DEVICES.items():
            futures.append(ex.submit(collect_mikrotik, name, params))
        for name, params in HOSTS.items():
            futures.append(ex.submit(collect_host, name, params))
        for f in as_completed(futures):
            name, results = f.result()
            all_results[name] = results
            print(f"  collected {name}", file=sys.stderr)

    # Print results grouped
    for group_name, devices in [("VYOS", VYOS_DEVICES), ("MIKROTIK", MIKROTIK_DEVICES), ("HOSTS", HOSTS)]:
        for name in devices:
            print(f"\n{'='*60}")
            print(f"  {name}")
            print(f"{'='*60}")
