GUEST = ["B4-PC3","B4-PC4"]

def ping_from_host(host_name, host_info, target_ip):
    try:
        conn = ConnectHandler(
            host=host_info["host"],
            device_type="linux",
            username="root",
            password="alpine",
        )
        out = conn.send_command(f"ping -c 2 -W 3 {target_ip}", read_timeout=15)
        conn.disconnect()
        m = re.search(r'(\d+) received', out)
        received = int(m.group(1)) if m else 0
